import { test } from "node:test";
import assert from "node:assert/strict";
import { truncate } from "../src/strings.ts";

test("short strings are unchanged", () => {
  assert.equal(truncate("abc", 5), "abc");
  assert.equal(truncate("abcde", 5), "abcde");
});

test("long strings are cut to exactly width including the ellipsis", () => {
  assert.equal(truncate("scheduler", 6), "sched\u2026");
  assert.equal(Array.from(truncate("a".repeat(50), 10)).length, 10);
});

test("tiny widths", () => {
  assert.equal(truncate("abc", 1), "\u2026");
  assert.equal(truncate("abc", 0), "");
  assert.equal(truncate("abc", -3), "");
});

test("multi-byte characters count once", () => {
  assert.equal(truncate("\u{1F600}\u{1F600}\u{1F600}", 3), "\u{1F600}\u{1F600}\u{1F600}");
  assert.equal(truncate("caf\u00e9 cr\u00e8me", 5), "caf\u00e9\u2026");
  assert.equal(truncate("\u{1F600}\u{1F600}\u{1F600}\u{1F600}", 3), "\u{1F600}\u{1F600}\u2026");
});
